<?php use SPFPU\Core\View; ?>
<header class="page-head"><div><p class="eyebrow">Merentas rekod dibenarkan</p><h1>Carian Global</h1><p>Cari kandungan entri, tarikh dan lokasi fail. Hasil sentiasa ditapis mengikut akses anda.</p></div></header>
<form class="filter-panel" method="get" data-filter-form><div class="search-primary"><label class="sr-only" for="search-q">Teks carian</label><input id="search-q" name="q" value="<?=View::e($_GET['q']??'')?>" placeholder="Perkara, pihak, catatan atau fail"><button class="button primary">Cari</button><button type="button" class="button quiet filter-toggle" data-filter-toggle>Penapis</button></div><div class="filter-fields" data-filter-fields><label>Jenis<select name="type"><option value="">Semua</option><option value="Incoming" <?=($_GET['type']??'')==='Incoming'?'selected':''?>>Masuk</option><option value="Outgoing" <?=($_GET['type']??'')==='Outgoing'?'selected':''?>>Keluar</option></select></label><label>Kategori<select name="category"><option value="">Semua</option><?php foreach($categories as $c):?><option value="<?=(int)$c['id']?>" <?=($_GET['category']??'')==$c['id']?'selected':''?>><?=View::e($c['name'])?></option><?php endforeach?></select></label><label>Tarikh dari<input type="date" name="date_from" value="<?=View::e($_GET['date_from']??'')?>"></label><label>Tarikh hingga<input type="date" name="date_to" value="<?=View::e($_GET['date_to']??'')?>"></label></div><div class="filter-actions"><span><?=count($results)?> hasil pada halaman ini</span><a class="button quiet" href="/carian/eksport?<?=http_build_query($_GET)?>">Eksport semua CSV</a></div></form>
<div class="table-wrap search-table"><table><thead><tr><th>Lokasi</th><th>Bil.</th><th>Jenis</th><th>Surat Bertarikh</th><th>Daripada/Kepada</th><th>Perkara</th></tr></thead><tbody><?php if(!$results):?><tr><td colspan="6" class="table-empty">Tiada rekod sepadan ditemui.</td></tr><?php endif?><?php foreach($results as $r):?><tr><td data-label="Lokasi"><a href="/fail/<?=(int)$r['folder_id']?>?jilid=<?=(int)$r['volume_id']?>"><strong><?=View::e($r['reference_code'])?></strong><small><?=View::e($r['category_name'])?> · Jilid <?=(int)$r['sequence_no']?></small></a></td><td data-label="Bil."><?=(int)$r['entry_no']?></td><td data-label="Jenis"><?=View::e($r['type']==='Incoming'?'Masuk':'Keluar')?></td><td data-label="Surat Bertarikh"><?=View::date($r['letter_date'])?></td><td data-label="Daripada/Kepada"><?=View::e($r['correspondent'])?></td><td data-label="Perkara" class="matter"><?=View::e($r['matter'])?></td></tr><?php endforeach?></tbody></table></div>
<nav class="pagination"><a class="button quiet <?=$page<=1?'disabled':''?>" href="?<?=http_build_query(array_merge($_GET,['page'=>max(1,$page-1)]))?>">← Sebelum</a><span>Halaman <?=$page?></span><a class="button quiet <?=count($results)<50?'disabled':''?>" href="?<?=http_build_query(array_merge($_GET,['page'=>$page+1]))?>">Seterusnya →</a></nav>
